int zuhe_next_incur(int c, int n, int l) {
	if (n == 1) return c;
	if ((c & (1 << l)) == 0) {
		int d = intlow2(c);
		c = (c & ~d);
		c = (c | (d >> 1));
	} else {
		c = (c & ~(1 << l));
		c = zuhe_next_incur(c, n - 1, l + 1);
		int d = intlow2(c);
		c = (c | (d >> 1));
	}
	return c;
}
